// MergeIntervals takes a slice of intervals (each interval is a two-element
// slice [start, end]) and merges all overlapping intervals, returning the
// merged result in sorted order by start time.
func MergeIntervals(in [][]int) [][]int {
	if len(in) == 0 {
		return nil
	}

	// Sort intervals by start time
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	merged := make([][]int, 0, len(in))
	merged = append(merged, in[0])

	for i := 1; i < len(in); i++ {
		last := merged[len(merged)-1]
		cur := in[i]

		if cur[0] <= last[1] {
			// Overlapping: extend the end if needed
			if cur[1] > last[1] {
				last[1] = cur[1]
			}
		} else {
			// No overlap: add new interval
			merged = append(merged, cur)
		}
	}

	return merged
}

